<?php
function om_filtered_orders($input){$sql='SELECT o.*,u.name owner_name FROM om_orders o LEFT JOIN users u ON u.id=o.owner_id WHERE 1=1';$args=[];foreach(['platform','shop','posting','platform_status','monitoring','owner_id'] as $k)if(($input[$k]??'')!==''){$sql.=' AND o.'.$k.'=?';$args[]=$input[$k];}if(!empty($input['q'])){$sql.=' AND o.order_no LIKE ?';$args[]='%'.trim($input['q']).'%';}if(!empty($input['from'])){$sql.=' AND o.fulfillment_date>=?';$args[]=report_date($input['from']);}if(!empty($input['to'])){$sql.=' AND o.fulfillment_date<=?';$args[]=report_date($input['to']);}$rows=om_query($sql.' ORDER BY o.fulfillment_date,o.id',$args)->fetchAll();$cfg=om_alert_settings();return array_values(array_filter($rows,function($o)use($input,$cfg){$age=(int)floor((strtotime(date('Y-m-d'))-strtotime($o['fulfillment_date']))/86400);$view=$input['report_view']??'';if($view==='dispatch'&&(!in_array($o['platform_status'],['To Ship','Needs Checking','Unpaid'],true)||$o['posting']==='Reversed'))return false;if($view==='delivery'&&(!in_array($o['platform_status'],['Shipped'],true)||$o['posting']!=='Posted'))return false;if($view==='returns'&&(!$o['aftersales']||in_array($o['aftersales_resolution'],['Refund Only','Receipt Linked'],true)))return false;if($view==='exceptions'&&!$o['exception_text']&&!($o['posting']==='Not Posted'&&in_array($o['platform_status'],['Shipped','Delivered','Completed'],true)))return false;if($view==='open'&&$o['monitoring']==='Resolved'&&!$o['exception_text'])return false;if(($input['age']??'')==='high'&&($age<(int)$cfg['high_days']||$o['monitoring']==='Resolved'))return false;return true;}));}
function om_readiness($input){$rows=om_filtered_orders($input);$r=['Pending dispatch'=>0,'Shipped but not posted'=>0,'Missing / conflicting updates'=>0,'Stock / reservation shortages'=>0];foreach($rows as $o){if(in_array($o['platform_status'],['To Ship','Needs Checking'],true)&&$o['posting']==='Not Posted')$r['Pending dispatch']++;if(in_array($o['platform_status'],['Shipped','Delivered','Completed'],true)&&$o['posting']==='Not Posted')$r['Shipped but not posted']++;if($o['exception_text'])$r['Missing / conflicting updates']++;$short=false;foreach(om_query('SELECT product_id,qty FROM om_reservations WHERE order_id=? AND qty>0',[$o['id']]) as $v)if(om_available($v['product_id'])<0||om_available($v['product_id'],$o['platform'])<0)$short=true;if($short)$r['Stock / reservation shortages']++;}return $r;}
function om_report($input){if(($input['report_view']??'')==='source_exceptions')return os_exception_report($input);if(($input['monitor_layout']??'')==='grouped')return gm_report($input);$input['report_view']=$input['report_view']??'open';$view=$input['report_view']??'open';$rows=[];$heads=['Platform','Shop','Order ID','Fulfillment Date','Platform Status','Inventory Posting','Monitoring','Reserved Units','Pending Age (days)','Last Seen','Responsible User','Next Follow-up','After-sales','Resolution','Exception'];$title='Order Monitoring';
 if($view==='reservations'){return om_reservation_report($input)+['summary'=>[],'links'=>[],'filters'=>$input,'generated'=>date('Y-m-d H:i:s'),'user'=>current_user()['name'],'notes'=>['Physical stock is unchanged by reservations.']];}
 if($view==='readiness'){$heads=['Check','Orders','Action'];foreach(om_readiness($input) as $k=>$n)$rows[]=[$k,$n,$n?'Review before inventory count':'No issue detected'];$title='Inventory Readiness';}
 elseif($view==='history'){$heads=['Recorded At','Platform','Shop','Order ID','Event','Upload','Processed By','Details'];$allowed=array_column(om_filtered_orders($input),'id');foreach(db()->query('SELECT e.*,o.platform,o.shop,o.order_no,u.name actor FROM om_events e LEFT JOIN om_orders o ON o.id=e.order_id LEFT JOIN users u ON u.id=e.user_id ORDER BY e.id DESC') as $r)if(in_array($r['order_id'],$allowed))$rows[]=[$r['created_at'],$r['platform'],$r['shop'],$r['order_no'],$r['event_type'],$r['upload_id'],$r['actor'],$r['details_json']];$title='Order Status & Action History';}
 elseif($view==='uploads'){$heads=['Upload','Date','Kind','Platform','Shop','File','Status','Uploader','Results'];foreach(db()->query('SELECT b.*,u.name uploader FROM om_uploads b LEFT JOIN users u ON u.id=b.created_by ORDER BY b.id DESC') as $b){if(!empty($input['platform'])&&$input['platform']!==$b['platform'])continue;$rows[]=[$b['id'],$b['created_at'],$b['kind'],$b['platform'],$b['shop'],$b['filename'],$b['status'],$b['uploader'],$b['result_json']??''];}$title='Order Upload History';}
 else foreach(om_filtered_orders($input) as $o){$reserved=(int)om_query('SELECT COALESCE(SUM(qty),0) FROM om_reservations WHERE order_id=?',[$o['id']])->fetchColumn();$age=$o['monitoring']==='Resolved'?0:max(0,(int)floor((strtotime(date('Y-m-d'))-strtotime($o['fulfillment_date']))/86400));$rows[]=[$o['platform'],$o['shop'],(string)$o['order_no'],$o['fulfillment_date'],$o['platform_status'],$o['posting'],$o['monitoring'],$reserved,$age,$o['last_seen_at']??'Never checked',$o['owner_name'],$o['followup_date']??'',$o['aftersales'],$o['aftersales_resolution'],$o['exception_text']??''];}
 return ['title'=>$title,'headers'=>$heads,'rows'=>$rows,'summary'=>[],'links'=>[],'notes'=>['Reservation activity is separate from physical inflow/outflow. Reports reflect confirmed updates, not live marketplace status. Inventory readiness is a checklist; it does not block physical counting.'],'filters'=>$input,'generated'=>date('Y-m-d H:i:s'),'user'=>current_user()['name']];}
function om_reservation_report($input){$pid=(int)($input['product_id']??0);$from=report_date($input['from']??date('Y-m-01'));$to=report_date($input['to']??date('Y-m-d'));$sql='SELECT e.*,o.platform,o.shop,o.order_no,u.name actor,p.master_sku,p.name product FROM om_reservation_events e JOIN om_orders o ON o.id=e.order_id JOIN products p ON p.id=e.product_id LEFT JOIN users u ON u.id=e.user_id WHERE DATE(e.created_at) BETWEEN ? AND ?';$a=[$from,$to];if($pid){$sql.=' AND e.product_id=?';$a[]=$pid;}if(!empty($input['platform'])){$sql.=' AND o.platform=?';$a[]=$input['platform'];}$rows=[];foreach(om_query($sql.' ORDER BY e.id',$a) as $r){if(!empty($input['reference'])&&!str_contains(norm($r['order_no']),norm($input['reference'])))continue;$rows[]=[$r['created_at'],$r['master_sku'],$r['product'],$r['platform'],$r['shop'],(string)$r['order_no'],$r['event_type'],(int)$r['delta'],0,$r['actor']];}return ['title'=>'Order Reservation Activity','headers'=>['Recorded At','Master SKU','Product','Platform','Shop','Order ID','Activity','Reserved Change','Physical Change','Processed By'],'rows'=>$rows];}
function om_inventory_report($input){
 if(!access_report_allowed($input['report']))throw new Exception('Your role cannot access this report.');
 $f=report_filters($input);if($f['report']==='order_reservations')$r=om_reservation_report($f);else $r=om_report(array_merge($f,['report_view'=>'all']));return array_replace(['summary'=>[],'links'=>[],'notes'=>['Order reports use fulfillment registration dates. Reservation activity does not change physical stock.'],'generated'=>date('Y-m-d H:i:s'),'user'=>current_user()['name']],$r,['filters'=>$f]);
}
function om_product_activity($pid,$f){
 $params=$_GET;$show=!empty($params['include_reservations']);$params['include_reservations']=$show?0:1;echo '<div class="card"><a class="btn secondary" href="?'.e(http_build_query($params)).'">'.($show?'Hide':'Include').' Reservation Activity</a><p class="muted">Reservation changes are shown separately; physical inflow/outflow totals remain unchanged.</p>';
 if($show){$input=$f+['product_id'=>$pid];$r=om_reservation_report($input);om_table($r['headers'],$r['rows']);echo '<div class="om-actions"><a class="btn secondary" href="order_monitor_action.php?'.e(http_build_query($input+['download'=>'reservations'])).'">Download Reservation Excel</a><a class="btn ghost" target="_blank" href="order_monitor_action.php?'.e(http_build_query($input+['download'=>'reservations','format'=>'print'])).'">Print / PDF</a></div>';foreach(om_query('SELECT DISTINCT o.id,o.order_no,o.platform FROM om_orders o JOIN om_reservations r ON r.order_id=o.id WHERE r.product_id=? ORDER BY o.id DESC LIMIT 30',[$pid]) as $o)echo '<a class="btn ghost sm" href="?page=order_monitor&order_id='.$o['id'].'">'.e($o['platform'].' / '.$o['order_no']).'</a>';}
 echo '</div>';
}
